BEGIN READ ONLY;SET LOCAL statement_timeout='10s';WITH actor AS(SELECT id FROM auth.users WHERE lower(email)=lower('majaribiopro@gmail.com') AND id='bb2d6dee-773d-4fa7-8fda-1eb85bbad2cd'::uuid),member_orgs AS(SELECT organization_id FROM public.org_memberships m JOIN actor a ON m.user_id=a.id) SELECT jsonb_build_object('sales',EXISTS(SELECT 1 FROM public.sales r WHERE r.organization_id IN(SELECT organization_id FROM member_orgs)),'sale_payments',EXISTS(SELECT 1 FROM public.sale_payments r WHERE r.organization_id IN(SELECT organization_id FROM member_orgs)),'inventory',EXISTS(SELECT 1 FROM public.inventory r WHERE r.organization_id IN(SELECT organization_id FROM member_orgs)),'stock_movements',EXISTS(SELECT 1 FROM public.stock_movements r WHERE r.organization_id IN(SELECT organization_id FROM member_orgs)),'expenses',EXISTS(SELECT 1 FROM public.expenses r WHERE r.organization_id IN(SELECT organization_id FROM member_orgs)),'cashier_shifts',EXISTS(SELECT 1 FROM public.cashier_shifts r WHERE r.organization_id IN(SELECT organization_id FROM member_orgs)),'field_wallets',EXISTS(SELECT 1 FROM public.field_wallets r WHERE r.organization_id IN(SELECT organization_id FROM member_orgs))) metadata;ROLLBACK;